SELECT location, budget_bucket, pct_chiang_mai, avg_budget FROM (SELECT location, CASE WHEN budget >= 3933000 THEN 'high' WHEN budget >= 1862000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN location = 'Chiang Mai' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_chiang_mai, AVG(budget) AS avg_budget FROM departments GROUP BY location, CASE WHEN budget >= 3933000 THEN 'high' WHEN budget >= 1862000 THEN 'mid' ELSE 'low' END) AS sub WHERE pct_chiang_mai >= 79 ORDER BY budget_bucket DESC;
